package aippatch

import (
	"context"
	"sync/atomic"

	"github.com/jackc/pgx/v5"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/fieldmaskpb"
)

// Mapping is the static description of how a proto message round-trips
// through a SQL table. Generated by aippatchgen; never hand-edited.
type Mapping[T proto.Message] struct {
	Table      string
	PK         string
	SoftDelete string
	EmptyMask  EmptyMaskPolicy
	Bindings   []Binding
	AutoSet    []AutoSetClause

	// Populated by Validate(); unexported.
	bindingsByProto  map[string]*Binding
	bindingsByColumn map[string]*Binding
	codecs           map[string]EnumCodec
	validated        atomic.Bool
}

// Binding pairs one proto field with one SQL column.
type Binding struct {
	Proto    string
	Column   string
	SQLType  string
	Writable bool
	Codec    string
}

// AutoSetClause defines a SQL expression always written into the SET clause.
// The SQLLiteral is emitted as raw SQL — codegen guarantees Column matches
// [A-Za-z_][A-Za-z0-9_]* and SQLLiteral is a single Postgres expression
// (validated at codegen time, not at runtime).
type AutoSetClause struct {
	Column     string
	SQLLiteral string
}

// EnumCodec maps a proto enum to/from a SQL text column. ToText is declared
// in aippatch.yaml; FromText is built by Validate from ToText.
type EnumCodec struct {
	ProtoEnum string
	ToText    map[int32]string
	FromText  map[string]int32
}

// Op carries a single PATCH invocation's runtime data.
type Op[T proto.Message] struct {
	Message T
	Mask    *fieldmaskpb.FieldMask
	PKValue any
	Where   map[string]any
}

// DBTX is the minimal pgx interface aippatch needs. Satisfied by *pgxpool.Pool,
// *pgx.Conn, and pgx.Tx — Apply participates in a caller's transaction
// transparently when a tx is passed.
type DBTX interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

// EmptyMaskPolicy controls behavior when Op.Mask has zero paths.
type EmptyMaskPolicy int

const (
	// ErrorOnEmpty is the v0 default; rejects empty mask with InvalidArgument.
	ErrorOnEmpty EmptyMaskPolicy = iota
	// UpdateAllWritable is reserved for v1; v0 returns Unimplemented.
	UpdateAllWritable
)
